def fill_blanks(template, words):
    result = template
    for w in words:
        result = result.replace('___', w, 1)
    return result

def histogram_bins(nums, bin_size):
    d = {}
    for x in nums:
        b = (x // bin_size) * bin_size
        d[b] = d.get(b, 0) + 1
    return d

def is_palindrome(s):
    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]

def count_local_maxima_including_endpoints(lst):
    n = len(lst)
    if n == 0:
        return 0
    if n == 1:
        return 1
    count = 0
    if lst[0] > lst[1]:
        count += 1
    if lst[n - 1] > lst[n - 2]:
        count += 1
    for i in range(1, n - 1):
        if lst[i] > lst[i - 1] and lst[i] > lst[i + 1]:
            count += 1
    return count

def days_in_month(year, month):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if month == 2 and (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)):
        return 29
    return lengths[month-1]

def longest_increasing_run_length(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def find_all_occurrence_indices(s, sub):
    if not sub:
        return []
    indices = []
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        indices.append(idx)
        start = idx + 1
    return indices

def tally_votes(votes):
