def is_valid_base64_format(s):
    if not s or len(s) % 4 != 0:
        return False
    if s.count('=') > 2:
        return False
    core = s.rstrip('=')
    if '=' in core:
        return False
    alphabet = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    return all(c in alphabet for c in core)

def compress_to_tuples(s):
    if not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = c
            count = 1
    result.append((prev, count))
    return result

def weekday_name_from_index(index):
    names = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']
    return names[index % 7]

def wrap_preserve_paragraphs(text, width):
    paragraphs = text.split("\n")
    result = []
    for para in paragraphs:
        words = para.split()
        lines = []
        cur = ""
        for word in words:
            if not cur:
                cur = word
            elif len(cur) + 1 + len(word) <= width:
                cur += " " + word
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
        if not lines:
            lines = [""]
        result.append("\n".join(lines))
    return "\n".join(result)

def first_index_ge(lst, target):
    for i, x in enumerate(lst):
        if x >= target:
            return i
    return -1

def integer_sqrt_floor(n):
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def ordinal_word(n):
