def shift_time_by_hours(hh, mm, offset_hours):
    total = hh * 60 + mm + offset_hours * 60
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def rotate_list_right(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[-n:] + lst[:-n] if n != 0 else lst[:]

def is_practical_number(n):
    if n == 1:
        return True
    divs = sorted(i for i in range(1, n + 1) if n % i == 0)
    if divs[0] != 1:
        return False
    total = 1
    for d in divs[1:]:
        if d > total + 1:
            return False
        total += d
    return True

def sign_changes_count(lst):
    def sign(x):
        if x > 0:
            return 1
        if x < 0:
            return -1
        return 0
    count = 0
    for i in range(len(lst) - 1):
        if sign(lst[i]) != sign(lst[i + 1]):
            count += 1
    return count

def is_valid_business_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or local.startswith('.') or local.endswith('.') or '..' in local:
        return False
    if not all(c.isalnum() or c in '.+-' for c in local):
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label or label.startswith('-') or label.endswith('-'):
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    return labels[-1] in {'com', 'org', 'net', 'io'}

def dedupe_keep_first(lst):
    seen = set()
    out = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def is_one_edit_away(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        diffs = sum(1 for x, y in zip(a, b) if x != y)
        return diffs <= 1
    if la > lb:
        a, b = b, a
        la, lb = lb, la
    i = j = 0
    found_diff = False
    while i < la and j < lb:
        if a[i] != b[j]:
            if found_diff:
                return False
            found_diff = True
            j += 1
        else:
            i += 1
            j += 1
    return True

def is_balanced_parens(s):
    depth = 0
    for c in s:
        if c == '(':
            depth += 1
        elif c == ')':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

def invert_one_to_many(d):
    res = {}
    for k, v in d.items():
        res.setdefault(v, []).append(k)
    return {v: sorted(ks) for v, ks in res.items()}

def is_palindrome_in_base(n, base):
    digits = []
    x = n
    if x == 0:
        digits = [0]
    while x > 0:
        digits.append(x % base)
        x //= base
    return digits == digits[::-1]

def parse_duration_words(s):
    tokens = s.split(" ")
    total = 0
    i = 0
    while i < len(tokens):
        num = int(tokens[i])
        unit = tokens[i + 1]
        if unit.startswith("hour"):
            total += num * 60
        elif unit.startswith("minute"):
            total += num
        i += 2
    return total
